const icon = (name,cls='') => {const nodes=WORKSPACE_ICONS[name]||LUMI_ICONS[name]||LUMI_ICONS.CircleHelp;return `<svg class="ui-icon ${esc(cls)}" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${nodes.map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).map(([key,value])=>`${key}="${esc(value)}"`).join(' ')} />`).join('')}</svg>`;};
