const num = (v,d=0) => v == null || v === '' || !Number.isFinite(Number(v)) ? '—' : Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const money = v => v == null ? '—' : `¥ ${num(v,2)}`;
