const priceConfirmed = q => !quoteNeedsReview(q) && Boolean(q?.provider?.is_demo || (q?.price_terms?.confirmed===true && q?.price_terms?.currency==='CNY' && q?.price_terms?.unit==='piece' && q?.summary?.currency==='CNY' && q?.summary?.price_unit==='piece'));
const quoteMoney = (q,v) => priceConfirmed(q)?money(v):'—';
