const safeUrl = s => {if(typeof s!=='string')return '';if(/^\/api\/projects\/[a-f0-9]{12}\/(?:ies|manufacturing|spectral\/[a-f0-9]{16}\/file|cost-scenarios\/[a-f0-9]{16}\/(?:export|evidence)|revisions\/[a-f0-9]{16}\/files\/[a-f0-9]{16})$/.test(s))return s;if(/^\/api\/knowledge\/documents\/[a-f0-9]{16}\/file$/.test(s))return s;if(!/^https?:\/\//i.test(s.trim()))return '';try {const u=new URL(s.trim());return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const date = v => {try{return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'}).format(new Date(v));}catch{return '本地保存';}};
const observationDate = v => {try{const d=new Date(v);return new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Shanghai'}).format(d);}catch{return '日期未知';}};
let toastTimer;
function toast(text,error=false){const t=$('#toast');t.textContent=text;t.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',4200);}
async function api(path,method='GET',body){
 if(!path.startsWith('/api/auth/')&&path!=='/api/health'&&!state.authReady)throw new Error('请等待登录状态验证完成');
 if(!path.startsWith('/api/auth/')&&method!=='GET'&&method!=='HEAD'&&state.auth.mode==='online'&&['viewer','member'].includes(state.auth.user?.role))throw new Error('当前账号为只读查看者，请联系管理员授予编辑权限');
 const headers=body?{'Content-Type':'application/json'}:{};
 const csrf=window.LumiAuth?.account?.csrf_token||state.auth?.csrf_token;
 if(method!=='GET'&&csrf)headers['X-CSRF-Token']=csrf;
 const r=await fetch(path,{method,credentials:'same-origin',headers,body:body?JSON.stringify(body):undefined});
 let data;try{data=await r.json();}catch{throw new Error('服务返回了无法读取的内容');}
 if(!r.ok){const error=new Error(data.message||data.error?.message||'操作失败');error.status=r.status;error.code=data.error?.code;
  if(state.auth.mode==='online'&&['login_required','approval_required','password_change_required'].includes(error.code)){state.authReady=false;location.assign('/login');}
  throw error;
 }return data;
}
function applyAuth(payload){
 state.auth=payload;
 const online=payload.mode==='online',manage=payload.can_manage===true;
 if($('#access-nav-label'))$('#access-nav-label').textContent=online?(manage?'账户与设置':'我的账户'):'账户与设置';
 const workspace=document.querySelector('.workspace-name small');if(workspace)workspace.textContent=online?'共享研发工作空间':'本地演示工作空间';
 const note=document.querySelector('.sidebar-note');if(note&&online)note.innerHTML='<span class="status-dot"></span><strong>线上工作台 · 统一保存</strong><p>获批成员共享服务器中的项目与资料。</p><span class="version">ONLINE / 1.0</span>';
 const pill=document.querySelector('.local-pill');if(pill&&online)pill.innerHTML='<span class="status-dot"></span>'+(payload.user?.role==='viewer'?'只读查看':'线上服务');
 window.LumiAuth?.setAuth(payload);
 window.LumiWorkspaceAccess?.setAuth(payload);
 window.LumiRoleWorkspace?.setAuth(payload);
 window.LumiRoleWorkspace?.update(routeInfo());
 hydrateIcons(document.querySelector('.sidebar')||document);
}
function renderAuthView(){
 if(state.page!=='access')return;
 applyAuth(window.LumiAuth.account);
 $('#content').innerHTML=accessSettingsLinks()+window.LumiAuth.view();hydrateIcons($('#content'));window.LumiAuth.afterRender();
}

function accessSettingsLinks(){const a=state.auth,allowed=!a.readonly&&!a.workspace_readonly&&(a.mode==='local'&&a.can_manage===true||a.mode==='online'&&a.user?.status==='approved'&&!a.user?.must_change_password&&!['viewer','member'].includes(a.user?.role)&&(Array.isArray(a.capabilities)?a.capabilities.includes('ai_manage'):['admin','manager'].includes(a.user?.role)));return allowed?'<div class="object-tool-links object-settings-links"><a class="button" href="#customers?settings=ai">'+icon('Settings')+'AI 设置与采集接口</a><span>管理模型连接、接口配置与可用状态</span></div>':'';}

function referenceSnapshot(r){const {visible_excerpt,jsonld_product,primary_spec_text,...proof}=r.source_evidence||{};return {...r,source_evidence:proof};}
function saveProject(p,allowNew=false){const i=state.projects.findIndex(x=>x.id===p.id);if(i<0&&!allowNew)throw new Error('项目已移出在用列表，请重新载入后再操作');if(i>=0&&p.updated_at&&state.projects[i].updated_at&&new Date(p.updated_at)<new Date(state.projects[i].updated_at))return state.projects[i];if(i<0)state.projects.unshift(p);else state.projects[i]=p;updatePicker();if(state.page==='optical'&&p.id===state.activeId&&$('#optical-input-label'))$('#optical-input-label').textContent=`灯具目标 ${num(p.spec.power_w,1)} W / ${num(p.spec.luminous_flux_lm)} lm · ${p.photometry?'已保存输入：'+p.photometry.filename:'当前为概念预览'}`;return p;}
function updatePicker(){const select=$('#project-picker');select.innerHTML='<option value="">请选择项目</option>'+state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===state.activeId?'selected':''}>${esc(p.name)}</option>`).join('');$('#new-country').innerHTML=state.countries.map(c=>`<option value="${esc(c.code)}">${esc(c.name)}</option>`).join('');}
function options(values,selected){return values.map(([value,label])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');}
function countryOptions(selected,all=true){return options([...(all?[['ALL','全部国家']]:[]),...state.countries.map(c=>[c.code,c.name])],selected);}
function routeInfo(){return window.LumiWorkspace.route(location.hash);}
function workspaceTabs(){const r=routeInfo();if(r.page==='cost')return `<nav class="workspace-nav" aria-label="成本核算工作区">${[['overview','成本总览'],['procurement','BOM 与采购报价'],['route','工艺路线与 MVA'],['compare','方案比较']].map(([v,t])=>`<a href="${esc(canonicalToolLink('#cost?view='+v))}" ${r.workspace===v?'class="active" aria-current="page"':''}>${t}</a>`).join('')}</nav>`;const groups={overview:[['projects','全部项目'],['overview','当前项目工作台']],optical:[['optical','配光与照度'],['optical?view=spectral','光谱与光质量']],market:[['market','竞品资料'],['crawler','品牌与采集']],bom:[['bom','电子 BOM 与报价'],['manufacturing','工艺加工测算']],knowledge:[['knowledge','国家准入标准'],['knowledge?view=documents','资料检索与上传'],['manufacturing?view=knowledge','制造工艺知识']]};const tabs=groups[r.section];if(!tabs)return '';return `<nav class="workspace-nav" aria-label="${esc(r.title)}工作区">${tabs.map(([hash,label])=>{const active=hash===(r.page==='knowledge'?(state.knowledgeMode==='documents'?'knowledge?view=documents':'knowledge'):r.page+(r.page==='optical'&&state.opticalMode==='spectral'?'?view=spectral':r.workspace==='knowledge'?'?view=knowledge':''));return `<a href="${esc(canonicalToolLink('#'+hash))}" ${active?'class="active" aria-current="page"':''}>${label}</a>`;}).join('')}</nav>`;}
function heading(title,subtitle,actions=''){const r=routeInfo();return `<div class="page-heading"><div><p class="eyebrow">${r.scope==='catalog'?'全局项目台账':r.scope==='project'?'当前项目 · 研发工作':'共享资料 · 可关联项目'}</p><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`+workspaceTabs();}
function notice(text,amber=false){return `<div class="notice ${amber?'amber':''}"><span class="notice-icon">${icon(amber?'TriangleAlert':'CircleHelp')}</span><span>${text}</span></div>`;}
function metric(label,value,note='',symbol=''){return `<div class="metric"><div class="metric-label">${label}<span class="metric-icon">${symbol?icon(symbol):''}</span></div><div class="metric-value">${value}</div><div class="metric-context">${note}</div></div>`;}
