function stageOptions(p){return {manufacturingCount:state.manufacturingCounts[p.id]};}
function projectTargetSummary(p){const s=p.spec||{},parts=[];for(const [key,unit,digits] of [['power_w','W',1],['luminous_flux_lm','lm',0],['cct_k','K',0],['cri','Ra',0]]){const value=s[key];if(typeof value==='number'&&Number.isFinite(value)&&(key==='cri'?value>=0&&value<=100:value>0))parts.push(key==='power_w'&&projectPowers(p).length>1?projectPowers(p).join(' / ')+' W':key==='cri'?'Ra '+num(value,digits):num(value,digits)+' '+unit);}const sales=window.LumiProjectInitiation?.summary(p);return [parts.length?parts.join(' · ')+'（设计目标）':'目标规格待补充',sales].filter(Boolean).join(' · ');}
function projectRecordBadges(p){const stages=LumiWorkspace.stages(p,stageOptions(p)),find=id=>stages.find(s=>s.id===id),plan=find('solution'),optical=find('optical'),bom=find('bom');const result=[{label:plan?.labelStatus||'方案待补充',tone:plan?.tone||''},{label:p.optical?.source_type==='concept'&&optical?.ready?'概念光学预览已存':optical?.labelStatus||'光度待补充',tone:optical?.tone||''},{label:p.spectral?(p.spectral.spec_changed?'光谱适用性待重审':'光谱计算已存 · 待核验'):'光谱待补充',tone:p.spectral?.spec_changed?'amber':p.spectral?'blue':''},{label:p.bom?.length?(p.bom_source==='generated_demo'?'演示BOM已存':'导入BOM已存'):'BOM待补充',tone:p.bom_source==='generated_demo'?'amber':p.bom?.length?'blue':''}];if(p.quote)result.push({label:bom?.labelStatus||'核价待确认',tone:bom?.tone||'amber'});return result;}
