function projectCostPanel(){const p=current(),data=state.costWorkspaces[p?.id];if(!p||!data)return '';const scenarios=Array.isArray(data.scenarios)?data.scenarios:[],issues=(data.issues||[]).filter(i=>i.status!=='resolved'),frozen=scenarios.filter(c=>c.status==='frozen');return `<section class="panel project-cost-summary"><div class="panel-header"><div><h3>整灯核价与待确认事项</h3><p>按产品版本检查报价、工艺与计费范围，责任人确认另留记录</p></div><a class="button button-small" href="#cost">进入成本工作区</a></div><div class="panel-body"><div class="project-cost-summary-counts"><span>产品基线 <strong>${num(data.revisions?.length||0)}</strong></span><span>成本方案 <strong>${num(scenarios.length)}</strong></span><span>已冻结 <strong>${num(frozen.length)}</strong></span><span>待处理 <strong>${num(issues.length)}</strong></span></div>${issues.length?`<div class="project-cost-issues">${issues.slice(0,6).map(i=>`<div><strong>${esc(i.title||i.code||'待确认')}</strong><small>${esc(i.owner||i.review?.owner||'责任人待分配')}${i.due_date?' · '+esc(i.due_date):''}</small></div>`).join('')}</div>`:'<p class="references-empty">'+(scenarios.length?'当前没有已计算方案的未完成确认事项，成本完整性与工程结论仍需分别核对。':'先保存产品基线，导入真实采购报价并建立成本方案。')+'</p>'}<p class="inline-note">A 灯泡与 T8 为首轮试点产品；真实工厂报价、节拍、良率与实绩尚需录入，原有演示报价不作为试点结论。</p></div></section>`;}
