function marketView(){const m=state.market;const filters=[['','全部来源市场'],...state.countries.map(c=>[c.code,c.name]),['Global','全球官方目录']];return heading('竞品资料库','浏览归档与采集证据，选择可追溯的参考，关联到右上角的引用项目。')+notice('这里包含历史代表样本与新增公开网页解析结果，采集时间单独标记。Global 是全球目录基线，不证明某个国家可售；缺失规格不会补造。历史价格保留原币种与商品包装，未统一单只 / 整箱口径。')+`<div class="library-summary"><span>历史归档</span><strong>${num(m.product_count)} 商品实体</strong><span>${num(m.brand_count)} 品牌档案</span><span>${num(m.report_count)} 来源报告</span><span>${num(m.sample_count)} 可浏览样本</span><small>归档总体，非当前搜索结果</small></div><div class="market-acquisition-note">${icon('Database')}<strong>新采集 ${num(m.collected_count||0)} 个产品</strong>${m.registry_count?`<span>品牌与企业名录 ${num(m.registry_count)} 条 · ${num(m.registry_region_count)} 个区域</span>`:''}<span>${m.last_collected_at?'最近采集 '+date(m.last_collected_at):'暂无实际采集记录'} · 页面已解析，待工程复核</span></div><section class="panel"><div class="panel-header"><div><h3>竞品产品库</h3><p>${state.marketDataset==='collected'?'用户触发的公开网页采集，按来源网址去重':state.marketDataset==='historical'?esc(m.sample_population||'历史代表样本'):'历史代表样本与新采集产品，按来源网址去重'} · 当前显示 ${state.products.length} 条</p></div></div><form id="market-filter" class="filters"><select name="dataset" aria-label="筛选资料批次">${options([['all','全部资料'],['collected','新采集资料'],['historical','历史样本']],state.marketDataset)}</select><select name="country" aria-label="筛选市场">${options(filters,state.marketCountry)}</select><select name="category" aria-label="筛选产品类型">${options([['','全部产品类型'],...Object.entries(MARKET_CATEGORIES)],state.marketCategory)}</select><input name="q" value="${esc(state.marketQuery)}" placeholder="搜索品牌、产品名称或关键词" aria-label="搜索竞品"><button class="button" type="submit">筛选</button></form>${state.products.length?`<div class="table-scroll"><table class="market-table"><colgroup><col style="width:31%"><col style="width:13%"><col style="width:15%"><col style="width:11%"><col style="width:19%"><col style="width:11%"></colgroup><thead><tr><th>品牌 / 产品</th><th>市场与类型</th><th>规格信息</th><th class="number">页面价格</th><th>资料来源</th><th>操作</th></tr></thead><tbody>${state.products.map(r=>`<tr><td class="product-name"><strong>${esc(r.brand||'品牌待核实')}</strong><span class="product-title" title="${esc(r.name)}">${esc(r.name)}</span><small>${esc(MARKET_CATEGORIES[r.category]||r.category_label||'待分类')}</small></td><td>${tag(country(r.country))}<div class="inline-note">${r.country==='Global'?'仅作设计基线':r.collected_at?'来源市场标记':'原档案市场标记'}</div></td><td class="product-spec-text">${r.power_range?esc(r.power_range)+'（目录范围）':r.power_w!=null?num(r.power_w,1)+' W':'功率待核验'}<br>${r.lumens!=null?num(r.lumens)+' lm':'光通量待核验'}<br>${r.cct!=null?esc(String(r.cct).replace(/\s*K$/i,''))+' K':''}${r.cri!=null?' · Ra '+esc(r.cri):''}</td><td class="number no-wrap">${r.price!=null?num(r.price,2)+'<small> '+esc(r.currency||'')+'</small>':'—'}</td><td><span class="source-badge">${r.evidence_status==='parsed_detail_unverified'?'新采集 · 待工程复核':r.evidence_type==='manual-benchmark'?'手工目录线索':r.source_type==='official-catalog'?'品牌官网归档':'电商历史页面'}</span><div class="source-name" title="${esc(r.source_label)}">${esc(r.source_label)}</div><div class="inline-note">${r.collected_at?'采集 '+date(r.collected_at):r.updated_at?'历史观测 '+observationDate(r.updated_at):'观测日期未知'}</div>${safeUrl(r.url)?`<a href="${esc(safeUrl(r.url))}" target="_blank" rel="noopener noreferrer">查看原始来源 ${icon('ArrowUpRight')}</a>`:''}</td><td class="no-wrap"><button class="button button-small" data-action="add-market" data-id="${esc(r.id)}">加入参考</button><br><button class="button-link" data-action="view-product" data-id="${esc(r.id)}">查看证据</button></td></tr>`).join('')}</tbody></table></div>`:empty('当前条件没有代表样本','可尝试全部产品类型或全球目录。没有样本不代表该国家没有需求。')}<div class="source-caption">${state.marketDataset==='collected'?'来源：本机采集任务及已保存的公开页面响应，具体网址和采集时间见每条记录。':`历史来源：${esc(m.source_label||'本地历史资料')}。归档更新时间 ${esc(m.as_of?observationDate(m.as_of):'未知')}；新采集按用户任务另记时间。`}</div></section>`;}
function specChips(p){const s=p.spec;return `<div class="spec-summary"><span class="spec-chip"><small>目标市场</small><strong>${esc(country(p.country))}</strong></span><span class="spec-chip"><small>产品形态 / 系列</small><strong>${esc(projectCategory(p))} · ${esc(projectPowers(p).join(' / '))} W</strong></span><span class="spec-chip"><small>目标光效</small><strong>${s.luminous_flux_lm>0?num(s.luminous_flux_lm/s.power_w,1):'待定义'} lm/W</strong></span><span class="spec-chip"><small>目标光通量</small><strong>${num(s.luminous_flux_lm)} lm</strong></span><span class="spec-chip"><small>批量测算</small><strong>${num(s.quantity)} 台</strong></span></div>`;}
function refsView(refs,kind='knowledge'){if(!refs?.length)return '<p class="references-empty">尚未关联资料。可从国家知识库上传文档，或在市场页面加入竞品参考。</p>';const rows=refs.map((r,i)=>{const u=safeUrl(r.url);return `<div class="ref-item"><strong>${i+1}. ${esc(r.title||r.name||r.filename||'项目参考资料')}</strong><p>${esc(String(r.excerpt||r.text||r.summary||r.source_label||r.brand||'项目引用').slice(0,140))}</p><div class="entry-meta">${tag(r.deleted?'引用已失效':r.source_type==='uploaded'?'上传资料':'参考来源',r.deleted?'amber':'')}${r.locator?tag(r.locator):''}${u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">查看来源 ${icon('ArrowUpRight')}</a>`:''}<button class="button-link" data-action="view-reference" data-reference-kind="${kind}" data-index="${i}">阅读摘录</button></div></div>`;});return `<div class="ref-list">${rows.slice(0,3).join('')}${rows.length>3?`<details class="evidence-disclosure"><summary>展开其余 ${rows.length-3} 条依据</summary>${rows.slice(3).join('')}</details>`:''}</div>`;}
function analysisSummary(p){const rows=[],o=p.optical?.summary||p.optical,m=p.spectral?.metrics;if(o)rows.push(`${p.optical?.spec_changed?'旧版本光学场景（规格已修改，需重新计算）：':'光学场景：'}平均照度 ${num(o.avgLux,1)} lx，最小/平均 ${num(o.uniformity,2)}；直接光计算，输入来源与条件待核验。`);if(m)rows.push(`上传光谱：CCT ${num(m.cct_k)} K / Duv ${num(m.duv,5)} / Ra ${num(m.cri?.ra,1)} / Rf ${num(m.tm30?.rf,1)} / Rg ${num(m.tm30?.rg,1)}；测量声明与型号适用性${p.spectral.spec_changed?'需重新审核':'待核验'}，未知指标显示为“—”。`);return rows;}
function readonlyLegacySolutionView(p){const plan=p.plan;return heading('产品信息与方案','只读查看原公开产品规格、工程方案与引用资料；销售目标未记录。')+`<section class="panel solution-scope-summary"><div class="panel-body"><h3>当前产品范围</h3><p>${esc(projectPowers(p).length?projectPowers(p).join(' / ')+' W':'瓦数待确认')} · ${esc((p.spec.cct_options_k||[]).length?p.spec.cct_options_k.join(' / ')+' K':'色温待确认')} · ${esc((p.spec.luminous_flux_options_lm||[]).length?p.spec.luminous_flux_options_lm.join(' / ')+' lm':'光通量待确认')}</p>${p.description?`<p>${esc(p.description)}</p>`:''}</div></section><details class="panel project-definition-editor"><summary>编辑产品规格与范围</summary>${window.LumiProductDefinition?.view(p)||''}</details><details class="panel solution-advanced-engineering"><summary>更多已记录产品要求 · 电压、尺寸、接口与性能</summary><div id="product-requirements-slot"></div></details><section class="panel"><div class="panel-header"><h3>原工程方案</h3>${tag(plan?'已保存工程方案':'工程方案未记录',plan?'blue':'amber')}</div><div class="panel-body">${plan?`<p class="page-summary">${esc(plan.summary||'已保存工程记录')}</p>${(plan.sections||[]).map(section=>`<div class="solution-section"><h3>${esc(section.title)}</h3><ul>${(section.items||[]).map(item=>`<li>${esc(typeof item==='string'?item:item.text||JSON.stringify(item))}</li>`).join('')}</ul></div>`).join('')}<p class="saved-time">原方案保存时间 · ${date(plan.generated_at||p.updated_at)}</p>`:empty('尚未保存工程方案','本次公开资料中没有该项目的已保存方案。')}</div></section><section class="panel"><div class="panel-header"><h3>原方案知识引用</h3></div><div class="panel-body">${refsView(plan?.references||[])}</div></section><section class="panel"><div class="panel-header"><h3>已关联竞品</h3><a class="button-link" href="#overview?view=intelligence">项目资料与竞品</a></div><div class="panel-body">${refsView(p.market_references||[],'market')}</div></section><details class="panel solution-advanced-engineering"><summary>产品版本与工程记录</summary><div id="product-versions-slot"></div></details>`+notice('以上内容来自原公开资料；销售数量、销售额及整灯 / 散件交付方式未记录。');}
function solutionView(){const p=current();if(!p)return empty('请先创建项目','项目是方案与分析结果的关联依据。');if(!window.LumiProductDefinition?.canEdit()&&!p.sales&&!p.sales_brief)return readonlyLegacySolutionView(p);const plan=p.sales_brief;return heading('销售产品信息与方案','按项目维护多个瓦数、色温与光通量，连接销售目标、客户要求和当地竞品。',`${plan?`<a class="button" href="/api/projects/${esc(p.id)}/sales-brief/export">导出项目销售方案</a>`:''}${window.LumiProductDefinition?.canEdit()?'<button class="button button-primary" data-definition-action="focus">填写产品信息</button>':''}`)+`<section class="panel solution-scope-summary"><div class="panel-body"><h3>当前产品范围</h3><p>${esc(projectPowers(p).length?projectPowers(p).join(' / ')+' W':'瓦数待确认')} · ${esc((p.spec.cct_options_k||[]).length?p.spec.cct_options_k.join(' / ')+' K':'色温待确认')} · ${esc((p.spec.luminous_flux_options_lm||[]).length?p.spec.luminous_flux_options_lm.join(' / ')+' lm':'光通量待确认')}</p>${p.description?`<p>${esc(p.description)}</p>`:''}</div></section><details class="panel project-definition-editor"><summary>编辑产品规格与范围</summary>${window.LumiProductDefinition?.view(p)||''}</details><details class="panel solution-advanced-engineering"><summary>更多产品要求（选填） · 电压、尺寸、接口与性能</summary><div id="product-requirements-slot"></div></details>`+(plan?.status==='needs_refresh'?notice('项目范围、销售目标或竞品资料已变化；重新生成销售方案后再核对。',true):'')+`<div class="grid-two solution-output-grid"><div><section class="panel"><div class="panel-header"><div><h3>2. 项目销售方案</h3><p>按销售范围、目标与已有项目依据整理待确认事项</p></div>${tag(plan?.status==='needs_refresh'?'需重新生成':plan?'已保存销售方案':'待生成销售方案',plan?.status==='needs_refresh'?'amber':plan?'teal':'amber')}</div><div class="panel-body">${plan?`<div class="page-summary">${esc(plan.summary||'根据当前产品定义和已关联知识形成研发草案。')}</div>${(plan.sections||[]).map((section,i)=>`<div class="solution-section"><h3><span class="section-number">${String(i+1).padStart(2,'0')}</span>${esc(section.title)}</h3><ul>${(section.items||[]).slice(0,3).map(item=>`<li>${esc(typeof item==='string'?item:item.text||JSON.stringify(item))}</li>`).join('')}</ul>${section.items?.length>3?`<details class="evidence-disclosure"><summary>核对详细依据与待验证项 · ${section.items.length-3} 项</summary><ul>${section.items.slice(3).map(item=>`<li>${esc(typeof item==='string'?item:item.text||JSON.stringify(item))}</li>`).join('')}</ul></details>`:''}</div>`).join('')}<p class="saved-time">根据已保存销售信息整理 · ${date(plan.generated_at||p.updated_at)}</p>`:empty('保存产品范围，再整理销售方案','可记录多个色温与光通量；未知规格保留待确认。')}</div></section><details class="panel solution-advanced-engineering"><summary>产品版本与工程记录（按需要查看）</summary>${p.plan?`<div class="panel-body"><h3>原工程方案与依据</h3><p class="inline-note">${esc(p.plan.summary||'已保存工程记录')}</p>${refsView(p.plan.references||[])}</div>`:''}<div id="product-versions-slot"></div></details></div><aside>${p.sales?`<details class="panel solution-sales-details"><summary>销售立项 · ${esc(window.LumiProjectInitiation?.summary(p)||'项目销售记录')}</summary><div class="panel-body">${window.LumiProjectInitiation?.saved(p)||''}<a class="button-link" href="#overview?view=intelligence">编辑销售立项与项目竞品</a></div></details>`:''}<section class="panel"><div class="panel-header"><h3>方案知识引用</h3><button class="button-link" data-action="navigate" data-page="knowledge">管理知识库 ${icon('ArrowRight')}</button></div><div class="panel-body">${refsView(plan?.references||[])}</div></section><section class="panel"><div class="panel-header"><h3>已关联竞品</h3><a class="button-link" href="#overview?view=intelligence">项目资料与竞品</a></div><div class="panel-body">${refsView(p.market_references||[],'market')}</div></section></aside></div>`+notice('销售方案整理已保存的产品范围与项目依据；价格、规格组合和当地在售情况仍需与客户确认。');}
function opticalStats(summary){const s=summary||{};const src={concept:'概念配光',demo:'合成样例','uploaded-unverified':'上传文件 · 来源待核验'}[s.sourceType]||'尚未分析';return [['平均照度',s.avgLux,'lx'],['最低照度',s.minLux,'lx'],['最高照度',s.maxLux,'lx'],['均匀度',s.uniformity,'Emin / Eavg']].map(([t,v,u])=>`<div class="optical-stat"><span>${t}</span><strong>${num(v,t==='均匀度'?3:1)}</strong><small>${u} · ${esc(src)}</small></div>`).join('');}
function opticalView(){const p=current();if(!p)return empty('请先创建项目','光学结果需要关联一个研发项目。');if(state.auth.mode==='online'&&['viewer','member'].includes(state.auth.user?.role))return readonlyOpticalView(p);const summary=p.optical?.spec_changed?null:p.optical?.summary||p.optical;return heading('配光与照度验证','读取配光，调整场景并预览直接照度；确认后保存到当前项目。',`<button class="button" data-action="upload-ies">导入 IES / LDT</button><button class="button" data-action="concept-ies">生成概念配光</button><button id="optical-save" class="button button-primary" data-action="save-optical" disabled>${icon('Check')}保存光学场景</button>`)+notice('<strong>计算范围：直接光。</strong> 未计反射、遮挡、日光及 UGR。概念 IES 用于方案探索，上传文件也需核验来源；不能代替正式测量与应用设计。',true)+(p.photometry?.spec_changed?notice('项目定义已改变；已有光度文件属于修改前版本。请核对适用性，必要时重新导入或生成概念配光，再计算并保存场景。',true):'')+`<section class="panel"><div class="panel-header"><div><h3>${esc(p.name)}</h3><p id="optical-input-label">灯具目标 ${num(p.spec.power_w,1)} W / ${num(p.spec.luminous_flux_lm)} lm，使用下方工作台调整场景${p.photometry?' · 已保存输入：'+esc(p.photometry.filename):' · 当前自动预览为概念配光'}</p></div><div class="optical-toolbar"><label>概念光束角<input id="concept-beam" type="number" min="10" max="160" value="${p.category==='t8'?120:90}">°（半峰全角）</label><button class="button button-small" data-action="download-ies">下载概念 IES</button></div></div></section><div id="optical-stats" class="optical-stats">${opticalStats(summary)}</div><div class="optical-preview-state" id="optical-preview-state" role="status">浏览已保存输入；场景预览仅在点击“保存光学场景”后写入项目。</div><section class="panel optical-workbench"><div class="optical-loading" role="status">正在载入已保存的光度文件与场景…</div><iframe id="optical-frame" class="optical-frame" inert title="IES / LDT 配光与直接光照度工作台" src="about:blank"></iframe></section>`;}
function readonlyOpticalView(p){
 const optical=p.optical,summary=optical?.spec_changed?null:optical?.summary||optical;
 return heading('配光与照度验证','只读查看已保存的光学分析与场景条件。')
  +notice('<strong>计算范围：直接光。</strong> 未计反射、遮挡、日光及 UGR；保存结果仍需核验输入来源与适用性。',true)
  +`<section class="panel"><div class="panel-header"><div><h3>${esc(p.name)}</h3><p>${esc(p.photometry?.filename||'尚未保存光度输入')}${optical?.spec_changed?' · 项目定义已改变，结果待更新':''}</p></div>${tag('已保存结果','blue')}</div><div class="panel-body"><div class="optical-stats">${opticalStats(summary)}</div><p class="inline-note">${summary?'以下为该项目已保存的场景。':'项目尚未保存照度结果，未知数值不会补造。'} 重新计算或保存需编辑权限。</p>${optical?.scene?`<details><summary>查看保存的场景条件</summary><pre class="account-saved-scene">${esc(JSON.stringify(optical.scene,null,2))}</pre></details>`:''}</div></section>`;
}
function quoteView(q){
 const p=current(), live=LumiSupplier.data.mode==='jlc_smt', lines=q?.lines||p.bom||[], termsKnown=q?priceConfirmed(q):!live; 
 if(!lines.length)return empty('还没有 BOM','导入工程 BOM 后查询物料；下载示例 BOM 可体验演示流程。');
 return `<div class="table-scroll"><table class="supplier-bom-table"><thead><tr><th>位号 / 物料规格</th><th>封装 / 用量</th>${live?'<th>供应查询编号</th>':''}<th>候选与确认</th><th class="number">需求 / 采购量</th><th class="number">${termsKnown?'单价 ¥ / 个':'单价（待定）'}</th><th class="number">${termsKnown?'小计 ¥':'小计（待定）'}</th></tr></thead><tbody>${lines.map(line=>{
 const cs=line.candidates||[];return `<tr><td class="bom-line-name"><strong>${esc(line.designators?.join(',')||line.category)}</strong><small>${esc(line.value_spec)}</small>${line.manufacturer_part_number?`<small>原厂型号 ${esc(line.manufacturer_part_number)}</small>`:''}</td><td>${esc(line.package||'待核对')}<small>单台 ${num(line.qty)} 个</small></td>${live?`<td>${LumiSupplier.rowQuery(p,line)}</td>`:''}<td>${tag(MATCH_LABELS[line.match_status]||'待查询',line.selected_item_id?'teal':'amber')}<div style="margin-top:8px">${cs.length?`<select class="candidate-select" data-line-id="${esc(line.line_id)}" aria-label="${esc(line.value_spec)}候选物料"><option value="">待人工确认</option>${cs.map(c=>`<option value="${esc(c.item_id)}" ${c.item_id===line.selected_item_id?'selected':''} ${c.selection_block_reason?'disabled':''}>${esc(c.item_id)} · ${esc(c.manufacturer_part_number||c.title)}${c.selection_block_reason?' · 禁选':''}</option>`).join('')}</select>`:`<span class="muted">${live?'填写 C 编号或精确型号':'执行演示核价获取候选'}</span>`}</div><div class="inline-note">${esc(line.pricing_reason||'')} ${(line.verification_notes||[]).map(esc).join('；')}</div>${cs.filter(c=>c.selection_block_reason).length?`<details class="inline-note"><summary>候选限制</summary>${cs.filter(c=>c.selection_block_reason).map(c=>`<p>${esc(c.item_id)}：${esc(c.selection_block_reason)}</p>`).join('')}</details>`:''}</td><td class="number">${num(line.requested_qty)} / ${num(line.procurement_qty)}<small>${line.moq_qty==null?'MOQ 未知':'MOQ '+num(line.moq_qty)}</small></td><td class="number">${termsKnown?num(line.unit_price,6):'—'}</td><td class="number currency">${termsKnown?num(line.extended_price,4):'—'}</td></tr>`;
 }).join('')}</tbody></table></div>`;
}
