function canonicalToolLink(hash, projectId=routeInfo().projectId) {
  if(typeof hash!=='string'||!hash.startsWith('#'))return hash;
  const target=window.LumiWorkspace.route(hash);
  if(projectId&&!target.projectId&&['overview','solution','optical','cost','bom','manufacturing','market','crawler','knowledge'].includes(target.page))return window.LumiWorkspace.projectHref(projectId,hash);
  return target.redirect||hash;
}
