window.LumiCost?.init({api,esc,icon,num,money,tag,empty,heading,toast,current,refresh:render,navigate,base64File,download,auth:()=>state.auth,shell:content=>{Promise.resolve().then(()=>{rewriteContextLinks();mountMaterialBindings();});return heading('产品成本与核价','按整灯或散件交付范围连接产品版本、采购、工艺与物流；保留原币种和税运口径。')+content+materialBindingView();}});
